            C++

    #include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> v = {11, 23, 45, 9};

  	// Checking whether a vector is empty before using
  	// vector front() method
    if (!v.empty()) {
        cout << v.front();
    } else {
        cout << "Vector is empty";
    }

    return 0;
}

Output11Explanation: Calling vector back() on an empty vector causes undefined behaviour. To prevent this, vector empty() is used.
